\label{lem:entropy-standard-bound}
Suppose $p,q$ are probability densities of random variables $U$ and $V$, respectively. Take $\Phi=-\ln q$. Then 
\begin{itemize}
	\item[(a)] $-\int p \ln p \leq - \int p \ln q$, that is, $h(U) \leq \mathbb{E}\Phi(U)$,
	\item[(b)] if $\mathbb{E} \Phi(U) \leq \mathbb{E} \Phi(V)$, then $h(U) \leq h(V)$.  
\end{itemize}

(a) We can assume that the support of $p$ is contained in the support of $q$ (otherwise the right-hand side is $+\infty$ and there is nothing to prove). Since for $x \geq 0$ we have $\ln x \leq x-1$, one gets
\begin{align*}
	-\int p \ln p  + \int p \ln q & = \int_{\mathrm{supp}(p)} (p \ln q- p \ln p) = \int_{\mathrm{supp}(p)} p \ln(q/p) \\ & \leq \int_{\mathrm{supp}(p)} p(q/p-1) \leq 0. 
\end{align*}

(b) From part (a) we have $h(U) \leq \mathbb{E} \Phi(U) \leq \mathbb{E} \Phi(V) = -\int q \ln q = h(V)$.

\begin{align*}
	-\int p \ln p  + \int p \ln q & = \int_{\mathrm{supp}(p)} (p \ln q- p \ln p) = \int_{\mathrm{supp}(p)} p \ln(q/p) \\ & \leq \int_{\mathrm{supp}(p)} p(q/p-1) \leq 0. 
\end{align*}

Let $f : \mathbb{R} \to \mathbb{R}$ be measurable function. We say that $f$ \emph{changes sign} at point $x \in \mathbb{R}$ if one of the following conditions holds:
\begin{itemize}
	\item[(a)] there exist $y, z \in \mathbb{R}$ such that $y < x < z$ and $f$ is positive a.e. on $(x, z)$, nonpositive a.e. on $(y, x)$ and negative on some subset of $(y, x)$ of positive measure;
	\item[(b)] there exist $y, z \in \mathbb{R}$ such that $y < x < z$ and $f$ is negative a.e. on $(x, z)$, nonnegative a.e. on $(y, x)$ and positive on some subset of $(y, x)$ of positive measure.  
\end{itemize}
We call such $x$ the \emph{sign change point} of $f$. If $f$ has precisely $n$ sign change points, then we say that $f$ \emph{changes sign exactly $n$ times}.

